def make_game(**overrides):
    """Build a dict-shaped game row with sensible defaults."""
    data = {
        "id": 1,
        "host_id": 100,
        "cohost_ids": "",
        "guild_id": "",
        "range_label": "2026-07-H1",
        "name": "Test Game",
        "description": "desc",
        "max_players": 10,
        "status": "pending",
        "discord_invite": "",
        "created_at": "2026-01-01T00:00:00+00:00",
    }
    data.update(overrides)
    return data


def make_player(**overrides):
    data = {"id": 1, "game_id": 1, "user_id": 555, "role": "player", "slot": 1}
    data.update(overrides)
    return data


@pytest.fixture
def db_path(tmp_path, monkeypatch):
    path = os.path.join(tmp_path, "test_calendar.db")
    monkeypatch.setattr(game_manager_en, "DB_PATH", path)
    game_manager_en.init_db()
    return path


def insert_game(db_path, **overrides):
    game = make_game(**overrides)
    with game_manager_en.get_db() as conn:
        conn.execute(
            "INSERT INTO Games (host_id, cohost_ids, guild_id, range_label, name, "
            "description, max_players, discord_invite, created_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                game["host_id"], game["cohost_ids"], game["guild_id"],
                game["range_label"], game["name"], game["description"],
                game["max_players"], game["discord_invite"], game["created_at"],
            ),
        )
    return game


