class TestInviteHelpers:
    """Unit tests for invite parsing and validation helpers."""

    def test_invite_code_from_urls(self):
        assert game_manager_en._invite_code("https://discord.gg/abc123") == "abc123"
        assert game_manager_en._invite_code("https://discord.com/invite/xyz") == "xyz"
        assert game_manager_en._invite_code("https://discordapp.com/invite/code_1") == "code_1"
        assert game_manager_en._invite_code("https://discord.gg/abc/") == "abc"

    def test_invite_code_from_bare_code(self):
        assert game_manager_en._invite_code("abcDEF123") == "abcDEF123"

    def test_invite_code_invalid(self):
        assert game_manager_en._invite_code("not a link") is None
        assert game_manager_en._invite_code("") is None

    @pytest.mark.asyncio
    async def test_check_invite_valid(self):
        bot = MagicMock()
        inv = MagicMock()
        inv.expires_at = None
        bot.fetch_invite = AsyncMock(return_value=inv)
        ok, label = await game_manager_en._check_invite(bot, "https://discord.gg/abc123")
        assert ok is True
        assert "Valid" in label

    @pytest.mark.asyncio
    async def test_check_invite_valid_with_future_expiry(self):
        bot = MagicMock()
        inv = MagicMock()
        inv.expires_at = datetime.now(timezone.utc) + timedelta(days=1)
        bot.fetch_invite = AsyncMock(return_value=inv)
        ok, label = await game_manager_en._check_invite(bot, "https://discord.gg/abc123")
        assert ok is True
        assert "expires" in label

    @pytest.mark.asyncio
    async def test_check_invite_past_expiry(self):
        bot = MagicMock()
        inv = MagicMock()
        inv.expires_at = datetime.now(timezone.utc) - timedelta(days=1)
        bot.fetch_invite = AsyncMock(return_value=inv)
        ok, label = await game_manager_en._check_invite(bot, "https://discord.gg/abc123")
        assert ok is False
        assert "expired" in label

    @pytest.mark.asyncio
    async def test_check_invite_expired(self):
        bot = MagicMock()
        bot.fetch_invite = AsyncMock(side_effect=discord.NotFound(MagicMock(), "gone"))
        ok, label = await game_manager_en._check_invite(bot, "https://discord.gg/abc123")
        assert ok is False

    @pytest.mark.asyncio
    async def test_check_invite_http_error(self):
        bot = MagicMock()
        bot.fetch_invite = AsyncMock(side_effect=discord.HTTPException(MagicMock(), "boom"))
        ok, label = await game_manager_en._check_invite(bot, "https://discord.gg/abc123")
        assert ok is None

    @pytest.mark.asyncio
    async def test_check_invite_unparsable(self):
        bot = MagicMock()
        ok, label = await game_manager_en._check_invite(bot, "not a link")
        assert ok is None
        assert "parse" in label


