        inter.response.edit_message = AsyncMock()
        await modal.on_submit(inter)
        assert modal.wizard.cohost_raw == "@100123456 @200123456"
        assert modal.wizard.guild_id_raw == "123456789012"
        wizard._build_cohost_step.assert_called_once()
        inter.response.edit_message.assert_awaited_once()


