class TestViews:
    @pytest.mark.asyncio
    async def test_calendar_view_empty(self, db_path):
        view = game_manager_en.CalendarView(MagicMock(), 100)
        embed = view.build_embed()
        assert "No games scheduled" in embed.description
        assert view._page_games == []

    @pytest.mark.asyncio
    async def test_calendar_view_pagination(self, db_path):
        for i in range(8):
            insert_game(db_path, id=i + 1, name=f"Game {i + 1}",
                        range_label=f"2026-{7 + i // 2:02d}-H{1 if i % 2 == 0 else 2}")
        view = game_manager_en.CalendarView(MagicMock(), 100, page=1)
        assert len(view._page_games) == 2
        view0 = game_manager_en.CalendarView(MagicMock(), 100, page=0)
        assert len(view0._page_games) == 6
        assert "No games scheduled" not in view.build_embed().description

    @pytest.mark.asyncio
    async def test_game_detail_view_non_manager(self):
        game = make_game(host_id=100, id=1)
        view = game_manager_en.GameDetailView(MagicMock(), game, invoker_id=999)
        labels = {c.label for c in view.children if getattr(c, "label", None)}
        assert "📋 Playerlist" in labels
        assert "⬅️ Back" in labels
        assert "🔗 Server Link" not in labels

    @pytest.mark.asyncio
    async def test_game_detail_view_manager_has_controls(self):
        game = make_game(host_id=100, id=1)
        view = game_manager_en.GameDetailView(MagicMock(), game, invoker_id=100)
        labels = {c.label for c in view.children if getattr(c, "label", None)}
        assert "🔗 Server Link" in labels
        emojis = {c.emoji.name for c in view.children if getattr(c, "emoji", None)}
        assert "🗑️" in emojis
        placeholders = {c.placeholder for c in view.children if getattr(c, "placeholder", None)}
        assert "🔄 Change Game Status…" in placeholders
        assert "✏️ Edit a field…" in placeholders

    @pytest.mark.asyncio
    async def test_playerlist_view(self, db_path):
        insert_game(db_path, max_players=10)
        game = make_game(host_id=100, id=1, max_players=10)
        view = game_manager_en.PlayerlistView(MagicMock(), game, invoker_id=999)
        placeholders = {c.placeholder for c in view.children if getattr(c, "placeholder", None)}
        assert any("role" in p for p in placeholders)

    @pytest.mark.asyncio
    async def test_playerlist_view_slot_select_when_role_chosen(self, db_path):
        game = make_game(host_id=100, id=1, max_players=10)
        view = game_manager_en.PlayerlistView(MagicMock(), game, invoker_id=999,
                                              chosen_role="player")
        placeholders = {c.placeholder for c in view.children if getattr(c, "placeholder", None)}
        assert any("slot" in p.lower() for p in placeholders)


